//! Safe wrappers around cb-mpc's TDH2 threshold decryption (`include/cbmpc/c_api/tdh2.h`).
//!
//! Used for the per-commitment (revocation) secrets: an offline ceremony encrypts each secret
//! under the parties' joint TDH2 public key, bound by a label to its kit and commitment number.
//! A secret can only be recovered when a quorum of parties (see [`Threshold`]) each contribute a
//! partial decryption, which each does only after its own policy allows the release.
//!
//! The key is generated by a distributed key generation; no party ever holds the decryption key.
//! It is a dedicated key and must never be one of the ECDSA signing keys.

use std::fmt;

use crate::cbmpc::{CbmpcError, ProtocolError};
use crate::ffi;
use crate::mp::{check, run_job, take_cmem, take_cmems, view, Flat, MpTransport, Names, Threshold};

/// This party's share of a TDH2 key, with the public material every party agrees on.
#[derive(Clone, PartialEq, Eq)]
pub struct Tdh2Key {
	/// The joint public key. Anyone can encrypt to it.
	pub public_key: Vec<u8>,
	/// The parties' names and public shares, in the order of the key generation.
	pub party_names: Vec<String>,
	pub public_shares: Vec<Vec<u8>>,
	/// This party's private share. Secret key material.
	pub private_share: Vec<u8>,
}

impl fmt::Debug for Tdh2Key {
	fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
		write!(f, "Tdh2Key(<{} parties>)", self.public_shares.len())
	}
}

impl Drop for Tdh2Key {
	fn drop(&mut self) {
		for b in self.private_share.iter_mut() {
			unsafe { std::ptr::write_volatile(b, 0) };
		}
	}
}

impl Tdh2Key {
	/// Serializes the key for storage.
	pub fn encode(&self) -> Vec<u8> {
		let mut out = vec![2u8];
		let mut put = |b: &[u8]| {
			out.extend_from_slice(&(b.len() as u32).to_be_bytes());
			out.extend_from_slice(b);
		};
		put(&self.public_key);
		put(&self.private_share);
		for (name, share) in self.party_names.iter().zip(&self.public_shares) {
			put(name.as_bytes());
			put(share);
		}
		out
	}

	pub fn decode(bytes: &[u8]) -> Result<Self, String> {
		if bytes.first() != Some(&2) {
			return Err("unknown TDH2 key version".into());
		}
		let mut rest = &bytes[1..];
		let mut items = Vec::new();
		while !rest.is_empty() {
			if rest.len() < 4 {
				return Err("truncated TDH2 key".into());
			}
			let len = u32::from_be_bytes(rest[..4].try_into().unwrap()) as usize;
			if rest.len() < 4 + len {
				return Err("truncated TDH2 key".into());
			}
			items.push(rest[4..4 + len].to_vec());
			rest = &rest[4 + len..];
		}
		if items.len() < 6 || items.len() % 2 != 0 {
			return Err("TDH2 key needs at least two parties".into());
		}
		let mut items = items.into_iter();
		let public_key = items.next().unwrap();
		let private_share = items.next().unwrap();
		let (mut party_names, mut public_shares) = (Vec::new(), Vec::new());
		while let (Some(name), Some(share)) = (items.next(), items.next()) {
			party_names.push(String::from_utf8(name).map_err(|_| "bad party name")?);
			public_shares.push(share);
		}
		Ok(Tdh2Key { public_key, party_names, public_shares, private_share })
	}

	/// This party's contribution to decrypting `ciphertext`. Sensitive: with a quorum's
	/// partial decryptions anyone can recover the plaintext, so only send it over an encrypted
	/// link to the party meant to combine them.
	pub fn partial_decrypt(&self, ciphertext: &[u8], label: &[u8]) -> Result<Vec<u8>, CbmpcError> {
		unsafe {
			let mut out = ffi::cmem_t::null();
			check(ffi::cbmpc_tdh2_partial_decrypt(
				view(&self.private_share),
				view(ciphertext),
				view(label),
				&mut out,
			))?;
			Ok(take_cmem(out))
		}
	}

	/// Recovers the plaintext from the partial decryptions of a quorum, given as
	/// `(party name, partial decryption)`.
	pub fn combine(
		&self, ac: &Threshold, ciphertext: &[u8], label: &[u8], partials: &[(String, Vec<u8>)],
	) -> Result<Vec<u8>, CbmpcError> {
		let all = Names::new(&self.party_names);
		let mut shares = Flat::new(&self.public_shares);
		let who: Vec<&str> = partials.iter().map(|(n, _)| n.as_str()).collect();
		let who = Names::new(&who);
		let parts: Vec<Vec<u8>> = partials.iter().map(|(_, p)| p.clone()).collect();
		let mut parts = Flat::new(&parts);
		ac.with_c(|c_ac| unsafe {
			let mut out = ffi::cmem_t::null();
			check(ffi::cbmpc_tdh2_combine_ac(
				c_ac,
				view(&self.public_key),
				all.as_ptr(),
				all.len(),
				shares.view(),
				view(label),
				who.as_ptr(),
				who.len(),
				parts.view(),
				view(ciphertext),
				&mut out,
			))?;
			Ok(take_cmem(out))
		})
	}
}

/// Runs the TDH2 distributed key generation among all parties of `ac` on secp256k1. `me` is
/// this party's index. Every party must take part.
pub fn dkg(
	ac: &Threshold, me: usize, transport: &dyn MpTransport,
) -> Result<Tdh2Key, ProtocolError> {
	let quorum = Names::new(&ac.parties);
	run_job(&ac.parties, me, transport, |job| {
		ac.with_c(|c_ac| unsafe {
			let mut public_key = ffi::cmem_t::null();
			let mut public_shares =
				ffi::cmems_t { count: 0, data: std::ptr::null_mut(), sizes: std::ptr::null_mut() };
			let mut private_share = ffi::cmem_t::null();
			let mut sid = ffi::cmem_t::null();
			check(ffi::cbmpc_tdh2_dkg_ac(
				job,
				ffi::CBMPC_CURVE_SECP256K1,
				ffi::cmem_t::null(),
				c_ac,
				quorum.as_ptr(),
				quorum.len(),
				&mut public_key,
				&mut public_shares,
				&mut private_share,
				&mut sid,
			))?;
			let _ = take_cmem(sid);
			Ok(Tdh2Key {
				public_key: take_cmem(public_key),
				party_names: ac.parties.clone(),
				public_shares: take_cmems(public_shares),
				private_share: take_cmem(private_share),
			})
		})
	})
}

/// Encrypts `plaintext` to the joint `public_key`, bound to `label`. Needs no secret.
pub fn encrypt(public_key: &[u8], plaintext: &[u8], label: &[u8]) -> Result<Vec<u8>, CbmpcError> {
	unsafe {
		let mut out = ffi::cmem_t::null();
		check(ffi::cbmpc_tdh2_encrypt(view(public_key), view(plaintext), view(label), &mut out))?;
		Ok(take_cmem(out))
	}
}

/// Checks that `ciphertext` is a well-formed encryption to `public_key` under `label`.
pub fn verify(public_key: &[u8], ciphertext: &[u8], label: &[u8]) -> Result<(), CbmpcError> {
	unsafe { check(ffi::cbmpc_tdh2_verify(view(public_key), view(ciphertext), view(label))) }
}

/// Helpers shared by this crate's unit tests.
#[cfg(test)]
pub(crate) mod test_util {
	use super::*;
	use crate::mp::test_util::{run_parties, threshold};

	/// A 3-of-4 TDH2 key: the access structure and each party's key.
	pub fn keys() -> (Threshold, Vec<Tdh2Key>) {
		let ac = threshold(4, 3);
		let ac2 = ac.clone();
		(ac, run_parties(4, move |i, mesh| dkg(&ac2, i, mesh).unwrap()))
	}

	/// Decrypts with the given parties' partial decryptions.
	pub fn decrypt(
		ac: &Threshold, keys: &[Tdh2Key], who: &[usize], ct: &[u8], label: &[u8],
	) -> Result<Vec<u8>, CbmpcError> {
		let mut partials = Vec::new();
		for i in who {
			partials.push((ac.parties[*i].clone(), keys[*i].partial_decrypt(ct, label)?));
		}
		keys[who[0]].combine(ac, ct, label, &partials)
	}
}

#[cfg(test)]
mod tests {
	use super::test_util::*;
	use super::*;

	#[test]
	fn any_three_of_four_decrypt_and_two_do_not() {
		let (ac, keys) = keys();
		assert!(keys.iter().all(|k| k.public_key == keys[0].public_key));
		assert!(keys.iter().all(|k| k.public_shares == keys[0].public_shares));

		let secret = [0x42u8; 32];
		let ct = encrypt(&keys[0].public_key, &secret, b"label-1").unwrap();
		verify(&keys[0].public_key, &ct, b"label-1").unwrap();
		for who in [[0, 1, 2], [0, 1, 3], [0, 2, 3], [1, 2, 3], [3, 0, 2]] {
			assert_eq!(decrypt(&ac, &keys, &who, &ct, b"label-1").unwrap(), secret, "{who:?}");
		}
		assert_eq!(decrypt(&ac, &keys, &[0, 1, 2, 3], &ct, b"label-1").unwrap(), secret);

		// Two parties are not enough, and one party counted twice is still two.
		assert!(decrypt(&ac, &keys, &[0, 1], &ct, b"label-1").is_err());
		let p0 = keys[0].partial_decrypt(&ct, b"label-1").unwrap();
		let p1 = keys[1].partial_decrypt(&ct, b"label-1").unwrap();
		let doubled = vec![
			(ac.parties[0].clone(), p0.clone()),
			(ac.parties[1].clone(), p1.clone()),
			(ac.parties[1].clone(), p1.clone()),
		];
		assert!(keys[0].combine(&ac, &ct, b"label-1", &doubled).is_err());
		// A partial decryption presented under another party's name is rejected.
		let p2 = keys[2].partial_decrypt(&ct, b"label-1").unwrap();
		let misnamed = vec![
			(ac.parties[0].clone(), p0),
			(ac.parties[1].clone(), p1),
			(ac.parties[3].clone(), p2),
		];
		assert!(keys[0].combine(&ac, &ct, b"label-1", &misnamed).is_err());
	}

	#[test]
	fn label_binds_the_ciphertext() {
		let (ac, keys) = keys();
		let ct = encrypt(&keys[0].public_key, &[7u8; 32], b"kit-1/100").unwrap();
		assert!(verify(&keys[0].public_key, &ct, b"kit-1/99").is_err());
		assert!(keys[0].partial_decrypt(&ct, b"kit-1/99").is_err());
		let partials: Vec<(String, Vec<u8>)> = (0..3)
			.map(|i| (ac.parties[i].clone(), keys[i].partial_decrypt(&ct, b"kit-1/100").unwrap()))
			.collect();
		assert!(keys[0].combine(&ac, &ct, b"kit-1/99", &partials).is_err());
	}

	#[test]
	fn key_round_trips_through_storage() {
		let (_, keys) = keys();
		assert_eq!(Tdh2Key::decode(&keys[0].encode()).unwrap(), keys[0]);
		assert!(Tdh2Key::decode(&[1, 0]).is_err());
	}
}
